-- Migration 0047: "Berlaku untuk" on production batch cost lines. A cost line can apply to one
-- product of a multi-product batch (e.g. Ongkos jahit Haura Rp39.000/pcs and Cyra Rp37.000/pcs in
-- one batch, one tailor bill). Expand-only: one nullable column. NULL = "Semua produk", which is
-- every existing line and every line the previous release inserts, with unchanged behaviour.
--
-- Generated by drizzle-kit, then hand-edited: appended the
-- production_batch_costs_scoped_quantity trigger. A scoped variable line's quantity must be its
-- product's pcs in the batch, never the batch total. The new release computes that itself; the
-- trigger makes the database recompute it on every insert/update, so the previous release (which
-- sets every variable line to the batch's total pcs on save and again at posting) can't inflate a
-- scoped line's total, and with it the supplier's bill, during a rollback. It also rejects any
-- scoped line whose product has no SKU in the batch. It fires only for scoped rows (WHEN
-- product_id IS NOT NULL), so batch-wide lines are untouched. Trigger order is by name:
-- prevent_posted_batch_cost_mutation (0007) runs first, so a posted batch is still rejected
-- before anything is recomputed.
ALTER TABLE "production_batch_costs" ADD COLUMN "product_id" uuid;--> statement-breakpoint
ALTER TABLE "production_batch_costs" ADD CONSTRAINT "production_batch_costs_product_id_products_id_fk" FOREIGN KEY ("product_id") REFERENCES "public"."products"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "production_batch_costs_product_id_idx" ON "production_batch_costs" USING btree ("product_id");--> statement-breakpoint

CREATE OR REPLACE FUNCTION production_batch_costs_scoped_quantity()
RETURNS trigger AS $$
DECLARE
  product_pcs integer;
BEGIN
  SELECT COALESCE(SUM(i.qty), 0)::integer INTO product_pcs
    FROM "production_batch_items" i
    JOIN "product_variants" v ON v.sku = i.sku
    WHERE i.production_batch_id = NEW.production_batch_id
      AND v.product_id = NEW.product_id;
  IF product_pcs = 0 THEN
    RAISE EXCEPTION 'cost line is scoped to a product with no SKU in this production batch'
      USING ERRCODE = 'check_violation', CONSTRAINT = 'production_batch_costs_product_in_batch_check';
  END IF;
  IF NEW.cost_type = 'variable' THEN
    NEW.quantity := product_pcs;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
--> statement-breakpoint

CREATE TRIGGER production_batch_costs_scoped_quantity BEFORE INSERT OR UPDATE ON "production_batch_costs"
  FOR EACH ROW WHEN (NEW.product_id IS NOT NULL) EXECUTE FUNCTION production_batch_costs_scoped_quantity();
